+export interface Manifest {
+  plan: string;
+  write(path: string | undefined): Promise<void>;
+}
+
+export async function mergeManifest(): Promise<Manifest> {
+  return {
+    plan: "no-op",
+    async write(path) {
+      if (path) await Bun.write(path, "{}");
+      else console.log("{}");
+    },
+  };
+}

